"""BGP Tracer — HCAF 4-way baseline comparison table."""
#!/usr/bin/env python3
from __future__ import annotations
import json
import sys
from datetime import datetime
from pathlib import Path

import csv
import os
from collections import Counter, defaultdict

ROOT = Path(__file__).resolve().parents[1]
IN_FILE = ROOT / "results" / "eval" / "hcaf_vs_baselines_v33.jsonl"
OUT_DIR = ROOT / "results" / "hcaf_4way"
OUT_DIR.mkdir(parents=True, exist_ok=True)

# Predictions produced before the Phase-2 audit were generated by code that
AUDIT_CUTOFF = datetime(2026, 10, 22)


def main() -> int:
    if not IN_FILE.exists():
        print(f"Missing: {IN_FILE}", file=sys.stderr)
        return 1
    rows = [json.loads(l) for l in open(IN_FILE)]
    # Rows without an expected direction (Tier-C attacker_view variants) have
    # nothing to be scored against; keeping them would inflate the denominator.
    rows = [r for r in rows if r.get("expected_direction")]
    if not rows:
        print(f"No scored rows in {IN_FILE}", file=sys.stderr)
        return 1
    pre_audit = datetime.fromtimestamp(IN_FILE.stat().st_mtime) < AUDIT_CUTOFF
    suffix = "_pre_audit" if pre_audit else ""
    if pre_audit:
        print(
            "WARNING: this JSONL predates the Phase-2 audit. Its predictions were "
            "produced by code that used the ground-truth event_type as a prior and "
            "counted abstentions as correct, so the table is NOT citable. "
            f"Writing to *{suffix}.* instead of the canonical name.",
            file=sys.stderr,
        )
    # Treat events with empty tier as Tier B (sparse data) for conservatism
    n = len(rows)
    n_a = sum(1 for r in rows if r["tier"] == "A")
    n_b = sum(1 for r in rows if r["tier"] == "B")
    n_other = sum(1 for r in rows if r["tier"] not in ("A", "B"))
    if n_other:
        n_b += n_other  # fold into B (sparse-data conservative)
    n_rt = sum(1 for r in rows if r["expected_direction"] == "routing_to_traffic")
    n_tr = sum(1 for r in rows if r["expected_direction"] == "traffic_to_routing")

    # Per-method stats
    methods = [
        ("HCAF (Pearl-PNS)", "hcaf_direction", "hcaf_correct"),
        ("CSS significant", "css_is_causal", None),  # boolean
        ("Transfer entropy", "transfer_entropy_direction", None),
        ("Timestamp distance", "ts_distance_direction", None),
        ("Granger causality", "granger_direction", None),
        ("Pearson lag", "pearson_direction", None),
        ("PC cond. indep.", "pc_conditional_independence_direction", None),
    ]

    table = []
    for label, dir_field, correct_field in methods:
        # Special-case CSS: use the estimator's *own* verdict when the run
        is_css = (dir_field == "css_is_causal")
        if not is_css and not any(dir_field in r for r in rows):
            # Field never recorded by this run (e.g. PC).  Emitting a 0/0 row
            # for it would read as "0% accuracy", which is not a measurement.
            print(f"  (skipping {label}: `{dir_field}` absent from {IN_FILE.name})",
                  file=sys.stderr)
            continue
        correct = 0
        unknown = 0
        wrong = 0
        for r in rows:
            if is_css:
                d = (
                    r.get("css_direction_engine")
                    or r.get("css_direction")
                    or "unknown"
                )
            else:
                d = r.get(dir_field)
            if d in (None, "unknown", "", "no_cache", "insufficient"):
                unknown += 1
            elif d == r["expected_direction"]:
                correct += 1
            else:
                wrong += 1
        acc = correct / n
        abst = unknown / n
        err = wrong / n
        committed = correct + wrong
        coverage = committed / n
        selective = correct / committed if committed else 0.0

        # Per-tier accuracy (fold non-A/B into B)
        a_correct = 0
        a_n = n_a
        b_correct = 0
        b_n = n_b
        for r in rows:
            if is_css:
                d = (
                    r.get("css_direction_engine")
                    or r.get("css_direction")
                    or "unknown"
                )
            else:
                d = r.get(dir_field)
            if d == r["expected_direction"]:
                if r.get("tier") == "A":
                    a_correct += 1
                else:
                    b_correct += 1

        table.append({
            "method": label,
            "n_total": n,
            "n_correct": correct,
            "n_abstain": unknown,
            "n_wrong": wrong,
            "acc_all": acc,
            "coverage": coverage,
            "selective_acc": selective,
            "acc_tier_a": a_correct / max(a_n, 1),
            "acc_tier_b": b_correct / max(b_n, 1),
            "abstain_rate": abst,
            "error_rate": err,
        })

    # Majority-class control: "always R→T", free of any telemetry.
    maj_a = sum(1 for r in rows if r.get("tier") == "A"
                and r["expected_direction"] == "routing_to_traffic")
    maj_b = n_rt - maj_a
    table.append({
        "method": "Majority (always R→T)",
        "n_total": n,
        "n_correct": n_rt,
        "n_abstain": 0,
        "n_wrong": n - n_rt,
        "acc_all": n_rt / n,
        "coverage": 1.0,
        "selective_acc": n_rt / n,
        "acc_tier_a": maj_a / max(n_a, 1),
        "acc_tier_b": maj_b / max(n_b, 1),
        "abstain_rate": 0.0,
        "error_rate": (n - n_rt) / n,
    })

    # Print summary
    print(f"HCAF 4-way baseline comparison (from {IN_FILE.name}, N={n})")
    print(f"Tier A (rich traffic data): {n_a}  Tier B (sparse): {n_b}")
    print(f"Expected directions: routing→traffic={n_rt}, traffic→routing={n_tr}")
    print()
    print("Accuracy = correct/N; an abstention is a cost, not a correct answer.")
    print(f"{'Method':<25} {'Acc':>7} {'Cov':>7} {'Sel':>7} {'Abst':>7} {'Err':>7} {'N':>4}")
    for t in table:
        print(f"  {t['method']:<23} {t['acc_all']*100:6.1f}% {t['coverage']*100:6.1f}% "
              f"{t['selective_acc']*100:6.1f}% {t['abstain_rate']*100:6.1f}% "
              f"{t['error_rate']*100:6.1f}% {t['n_total']:4d}")

    # Write CSV
    csv_path = OUT_DIR / f"hcaf_4way_table{suffix}.csv"
    with open(csv_path, "w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=list(table[0].keys()))
        w.writeheader()
        w.writerows(table)
    print(f"\nWrote {csv_path}")

    # Write Markdown
    md_lines = [
        "# HCAF 4-way baseline comparison",
        "",
    ]
    if pre_audit:
        md_lines += [
            "> **PRE-AUDIT ARTIFACT — DO NOT CITE.** The predictions in the source",
            "> JSONL were produced before the Phase-2 audit (label-leaking",
            "> `event_type` prior, abstention scored as correct). The metric below is",
            "> corrected, but the predictions are not; re-run the evaluation with the",
            "> current code before quoting any number.",
            "",
        ]
    md_lines += [
        f"Source: `{IN_FILE.relative_to(ROOT)}`  ·  N = {n} events "
        f"(Tier A: {n_a}, Tier B: {n_b})",
        "",
        f"- Expected direction `routing → traffic`: {n_rt} events",
        f"- Expected direction `traffic → routing`: {n_tr} events",
        "",
        "## Per-method table",
        "",
        "| Method | N | Correct | Abstain | Wrong | Acc = C/N | Coverage | Sel. acc | Abs. rate | Err. rate |",
        "|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|",
    ]
    for t in table:
        md_lines.append(
            f"| {t['method']} | {t['n_total']} | {t['n_correct']} | {t['n_abstain']} | "
            f"{t['n_wrong']} | {t['acc_all']*100:.1f}% | {t['coverage']*100:.1f}% | "
            f"{t['selective_acc']*100:.1f}% | {t['abstain_rate']*100:.1f}% | "
            f"{t['error_rate']*100:.1f}% |"
        )
    md_lines += [
        "",
        "## Reading guide",
        "",
        "- **Metric contract.** `Acc = C/N` counts an abstention as a cost, not "
        "a correct answer. `Coverage` is the share of events on which the method "
        "committed, and `Sel. acc` is correct over committed answers. A method "
        "that abstains everywhere has coverage 0 and selective accuracy 0/0 — "
        "that is not a perfect score.",
        "- **Majority control.** `always R→T` requires no telemetry; any method "
        "whose selective accuracy does not exceed it has demonstrated no "
        "directional skill on this set.",
        "- **HCAF (Pearl-PNS)** — the full engine. Its earlier 100% figures came "
        "from (a) scoring every baseline only on events the engine answered and "
        "(b) counting `unknown` as correct; both were removed in the Phase-2 "
        "audit, and the corrected counts are in this table.",
        "- **CSS significant** — CSS alone: the estimator commits only when its "
        "bootstrap interval excludes zero. On sparse Radar traffic it abstains "
        "often, which is why coverage is reported next to accuracy.",
        "- **Transfer entropy** — the strongest classical baseline here, but it "
        "was previously allowed to commit on a 1.2x ratio without a significance "
        "test and to test T→R against the R→T null; both defects are fixed, so "
        "these numbers are lower than the pre-audit ones and should be quoted "
        "instead of them.",
        "- **Timestamp distance / Granger / Pearson / PC** — included for "
        "completeness. Their abstention rates are a property of bursty BGP "
        "streams (non-stationary, sparse), not a tuning artefact.",
        "",
        "## Dependence caveat",
        "",
        "The channels are not independent: MSBD, CTPR, CIC, Granger and TE all "
        "read the same two time series. A leave-one-out ablation that shows zero "
        "direction flips is therefore evidence of dependence, not of robustness. "
        "The synthesis pools agreeing channels (geometric mean) so that repeated "
        "copies of one signal cannot multiply into confidence.",
    ]
    md_path = OUT_DIR / f"hcaf_4way_table{suffix}.md"
    with open(md_path, "w") as f:
        f.write("\n".join(md_lines) + "\n")
    print(f"Wrote {md_path}")

    return 0


if __name__ == "__main__":
    sys.exit(main())